class LauncherException(Exception):
    def __init__(self, log: Log, cause):
        log(Log.err, cause)

        super().__init__(cause)


def assets(name: str):
    return os.path.join(Main.assetsdir, name)


def validfile():
    if not os.path.exists(Main.workdir):
        os.mkdir(Main.workdir)

    elif not os.path.exists(Main.tempdir):
        os.mkdir(Main.tempdir)

    elif not os.path.exists(Main.logdir):
        os.mkdir(Main.logdir)

    elif not os.path.exists(Main.assetsdir):
        os.mkdir(Main.assetsdir)

    else:
        with open(Main.iconpath, 'wb') as icon:
            icon.write(iconmap)

        with open(assets('home.jpg'), 'wb') as homeimage:
            homeimage.write(homeimagemap)
